// Extract scholarships JSON from Claude's raw API response
// Claude returns content[] array with text and possibly tool_use/tool_result blocks
const fetchResponse = $('Fetch Scholarship List').item.json;
const contentBlocks = fetchResponse.content || [];

// Find the text blocks (skip tool_use and tool_result blocks from web search)
let scholarshipsText = '';
for (const block of contentBlocks) {
  if (block.type === 'text' && block.text) {
    scholarshipsText += block.text;
  }
}

// Extract JSON array from the text (may be wrapped in markdown code blocks)
let jsonStr = scholarshipsText;
const jsonMatch = scholarshipsText.match(/\[\s*\{[\s\S]*\}\s*\]/);
if (jsonMatch) {
  jsonStr = jsonMatch[0];
}

let scholarships;
try {
  scholarships = JSON.parse(jsonStr);
} catch (e) {
  // If parsing fails, return empty array
  scholarships = [];
}

return [{ json: { scholarships } }];

// Filter: eligible + automatable + no essay + difficulty <= 3 + not expired
const parseResponse = $('Parse Requirements').item.json;
const contentBlocks = parseResponse.content || [];

// Extract text from Claude response
let analysisText = '';
for (const block of contentBlocks) {
  if (block.type === 'text' && block.text) {
    analysisText += block.text;
  }
}

// Parse JSON array
let analyzed;
const jsonMatch = analysisText.match(/\[\s*\{[\s\S]*\}\s*\]/);
try {
  analyzed = JSON.parse(jsonMatch ? jsonMatch[0] : analysisText);
} catch (e) {
  analyzed = [];
}

// Apply filters
const filtered = analyzed.filter(s =>
  s.eligible === true &&
  s.automatable === true &&
  s.essay_required === false &&
  (s.difficulty || 5) <= 3 &&
  s.expired === false
);

return [{ json: { scholarships: filtered, count: filtered.length } }];

// Split scholarships array into individual n8n items, cap at 10
const scholarships = $('Filter Automatable').item.json.scholarships || [];
const capped = scholarships.slice(0, 10);

return capped.map(s => ({ json: s }));

// Parse the Claude Computer Use response and extract the result JSON
const response = $('Apply with Computer Use').item.json;
const contentBlocks = response.content || [];
const scholarship = $('Split Into Items').item.json;

let resultText = '';
for (const block of contentBlocks) {
  if (block.type === 'text' && block.text) {
    resultText += block.text;
  }
}

let result;
try {
  const jsonMatch = resultText.match(/\{[\s\S]*\}/);
  result = JSON.parse(jsonMatch ? jsonMatch[0] : resultText);
} catch (e) {
  result = {
    scholarship_id: scholarship.id || 'unknown',
    success: false,
    fields_filled: [],
    error_message: 'Failed to parse Claude response: ' + e.message,
    submitted: false
  };
}

// Merge scholarship info with result
return [{
  json: {
    Scholarship_ID: result.scholarship_id || scholarship.id || 'unknown',
    Scholarship_Name: scholarship.name || 'Unknown',
    URL: scholarship.url || '',
    Status: result.submitted ? 'Submitted' : 'Failed',
    Success: result.success ? 'Yes' : 'No',
    Submitted: result.submitted ? 'Yes' : 'No',
    Error_Message: result.error_message || '',
    Fields_Filled: (result.fields_filled || []).join(', '),
    Attempt_Date: new Date().toISOString().split('T')[0],
    Application_Amount: scholarship.amount || '',
    Deadline: scholarship.deadline || ''
  }
}];

// 5 second pause for rate limiting
await new Promise(resolve => setTimeout(resolve, 5000));

// Pass through current item for aggregation
return [$input.first()];

// Aggregate all results from the loop into summary stats
const allItems = $input.all();

const total = allItems.length;
const successful = allItems.filter(i => i.json.Success === 'Yes').length;
const failed = allItems.filter(i => i.json.Success === 'No').length;

// Build HTML table rows
const tableRows = allItems.map(i => {
  const j = i.json;
  return `<tr><td>${j.Scholarship_Name}</td><td>${j.Application_Amount}</td><td>${j.Status}</td><td>${j.Deadline}</td><td>${j.Error_Message || '-'}</td></tr>`;
}).join('');

const summaryHtml = `<h2>Daily Scholarship Bot Summary</h2>
<p><strong>Date:</strong> ${new Date().toISOString().split('T')[0]}</p>
<p><strong>Total Attempted:</strong> ${total}</p>
<p><strong>Successful:</strong> ${successful}</p>
<p><strong>Failed:</strong> ${failed}</p>
<table border="1" cellpadding="5" cellspacing="0">
<tr><th>Scholarship</th><th>Amount</th><th>Status</th><th>Deadline</th><th>Error</th></tr>
${tableRows}
</table>`;

return [{ json: { summaryHtml, total, successful, failed } }];
